// Version A: cache inside the real service
class UserService {
  private cache = new Map<number, User>();
  async getUser(id: number) {
    if (this.cache.has(id)) return this.cache.get(id)!;
    const u = await this.loadFromRemote(id);
    this.cache.set(id, u);
    return u;
  }
}

// Version B: separate forwarding type wraps the real service
class UserServiceImpl {
  async getUser(id: number) { return this.loadFromRemote(id); }
}
class CachingForwarder {
  constructor(private inner: UserServiceImpl) {}
  private cache = new Map<number, User>();
  async getUser(id: number) {
    if (this.cache.has(id)) return this.cache.get(id)!;
    const u = await this.inner.getUser(id);
    this.cache.set(id, u);
    return u;
  }
}
